input.sparql:
SELECT ?work ?workLabel ?lcsh ?fast WHERE {
  ?work wdt:P921 wd:Q17167 .  # main subject: Roman Republic
  ?work wdt:P31/wdt:P279* wd:Q732577 .  # instance of publication
  OPTIONAL { ?work wdt:P244 ?lcsh }  # LCSH ID
  OPTIONAL { ?work wdt:P2163 ?fast }  # FAST ID
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}
LIMIT 20

SELECT ?work ?workLabel WHERE {
  ?work wdt:P921 wd:Q17167 .
  ?work wdt:P31 wd:Q732577 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}
LIMIT 10

SELECT ?work ?workLabel ?author WHERE {
  ?work wdt:P921 ?subject .
  ?subject wdt:P279* wd:Q17167 .
  ?work wdt:P50 ?author .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}
LIMIT 10
